contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint balanceBefore = address(this).balance;

        // Fund C through its payable fallback (empty calldata matches no function).
        (bool ok, ) = address(c).call{value: amount}("");

        // Balance C now holds (its own, before any go() call).
        uint cBefore = address(c).balance;

        // State-changing call on c: go() must forward 0 value and sweep C's
        // whole balance to its owner (this contract).
        c.go{value: 0}();

        // Conservation: the fallback deposit sits in C (b0 == amount), and after
        // go() every wei of it is back with the owner, so this-balance + c-balance
        // equals exactly what we held minus what we deliberately transferred out.
        assert(ok && cBefore == amount && address(this).balance + address(c).balance == balanceBefore - amount + cBefore);
    }

    receive() external payable {}
}

